import{_ as a,o as s,c as e,a2 as n}from"./chunks/framework.mRCPFc5l.js";const b=JSON.parse('{"title":"前端调试技巧","description":"用断点、网络面板和性能分析系统化排查问题，而不是靠 console.log 猜。","frontmatter":{"title":"前端调试技巧","description":"用断点、网络面板和性能分析系统化排查问题，而不是靠 console.log 猜。"},"headers":[],"relativePath":"web/frontend/debugging.md","filePath":"web/frontend/debugging.md","lastUpdated":1786271684000}'),d={name:"web/frontend/debugging.md"};function i(o,t,l,p,r,h){return s(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="前端调试技巧" tabindex="-1">前端调试技巧 <a class="header-anchor" href="#前端调试技巧" aria-label="Permalink to &quot;前端调试技巧&quot;">​</a></h1><p>调试效率的差距不在工具，而在方法。看到 bug 就开始改代码试，往往改了十次还没定位；先观察、再假设、最后验证，可能三分钟就找到根因。本篇讲断点调试、网络面板、性能分析、移动端远程调试，以及一套通用的 bug 排查思路。把调试当作有章法的流程，而不是碰运气。</p><h2 id="先建立排查思路" tabindex="-1">先建立排查思路 <a class="header-anchor" href="#先建立排查思路" aria-label="Permalink to &quot;先建立排查思路&quot;">​</a></h2><p>面对一个 bug，别急着改代码。按这个顺序走：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 复现  → 稳定复现的 bug 才好定位</span></span>
<span class="line"><span>2. 隔离  → 二分法缩小范围（注释、回滚、最小复现）</span></span>
<span class="line"><span>3. 观察  → 看实际值，而不是猜值</span></span>
<span class="line"><span>4. 假设  → 提出&quot;可能是什么导致了这个&quot;</span></span>
<span class="line"><span>5. 验证  → 改一处，看现象是否变化</span></span></code></pre></div><table tabindex="0"><thead><tr><th>反模式</th><th>问题</th></tr></thead><tbody><tr><td>改代码看现象，反复试</td><td>每次改动引入新变量，越来越乱</td></tr><tr><td>只看代码不运行</td><td>脑内执行不可靠，尤其是异步</td></tr><tr><td>假设&quot;应该是这样&quot;</td><td>实际值和假设值常常不一样</td></tr></tbody></table><blockquote><p>最容易卡住的时刻，往往是&quot;我确定这里没问题&quot;。放下假设，去打印实际值。</p></blockquote><h2 id="断点调试-比-console-log-强得多" tabindex="-1">断点调试：比 console.log 强得多 <a class="header-anchor" href="#断点调试-比-console-log-强得多" aria-label="Permalink to &quot;断点调试：比 console.log 强得多&quot;">​</a></h2><p><code>console.log</code> 适合快速看一眼值，但复杂问题（异步、闭包、状态变化）断点调试更高效。断点能让你<strong>暂停在某个时刻，查看所有变量的真实值，并逐步执行</strong>。</p><table tabindex="0"><thead><tr><th>调试方式</th><th>用途</th></tr></thead><tbody><tr><td>普通断点</td><td>暂停在某行</td></tr><tr><td>条件断点</td><td>表达式为真才暂停（如 <code>i === 100</code>）</td></tr><tr><td>日志断点</td><td>不暂停，只打印（替代临时 console.log）</td></tr><tr><td>DOM 断点</td><td>元素被修改/删除时暂停</td></tr><tr><td>XHR/Fetch 断点</td><td>某个请求发出时暂停</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 在 Sources 面板：</span></span>
<span class="line"><span>// 1. 点行号加断点</span></span>
<span class="line"><span>// 2. 右键断点 → Edit breakpoint → 加条件</span></span>
<span class="line"><span>// 3. 用 Step over / Step into / Step out 逐步执行</span></span>
<span class="line"><span>// 4. 右侧 Scope 查看所有变量真实值</span></span></code></pre></div><p>条件断点特别有用——循环里某次迭代出问题，设 <code>i === 9527</code> 直接停在出错那次，不用手动跳过前 9526 次。</p><p>DOM 断点定位&quot;谁改了 DOM&quot;：在元素上右键 → Break on → attribute modifications / subtree modifications / node removal，DOM 被改时自动暂停到改它的代码。</p><h2 id="sources-面板的小技巧" tabindex="-1">Sources 面板的小技巧 <a class="header-anchor" href="#sources-面板的小技巧" aria-label="Permalink to &quot;Sources 面板的小技巧&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>- Call Stack：查看调用栈，点哪一层跳到哪层代码</span></span>
<span class="line"><span>- Watch：监视表达式，断点暂停时看它的值</span></span>
<span class="line"><span>- Scope：当前作用域所有变量（闭包也能看到）</span></span>
<span class="line"><span>- 黑盒脚本（Blackbox）：把库代码标记为不进入，单步时跳过</span></span></code></pre></div><p>把 Vue/React 源码、第三方库加入黑盒，单步执行时不会陷进库内部，只在自己的业务代码里走。</p><h2 id="网络面板-api-问题先看这里" tabindex="-1">网络面板：API 问题先看这里 <a class="header-anchor" href="#网络面板-api-问题先看这里" aria-label="Permalink to &quot;网络面板：API 问题先看这里&quot;">​</a></h2><p>很多&quot;前端 bug&quot;其实是接口问题。Network 面板能看清每个请求的全过程：</p><table tabindex="0"><thead><tr><th>检查项</th><th>看什么</th></tr></thead><tbody><tr><td>请求 URL 和方法</td><td>对不对？参数有没有错？</td></tr><tr><td>请求头</td><td>Authorization、Content-Type 对吗？</td></tr><tr><td>请求体</td><td>发出去的数据对吗？</td></tr><tr><td>状态码</td><td>200/400/401/404/500 各意味什么</td></tr><tr><td>响应体</td><td>后端返回了什么？是错误信息还是空？</td></tr><tr><td>Timing</td><td>是慢在 DNS、连接还是服务端处理？</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>常见误判：</span></span>
<span class="line"><span>- &quot;数据没显示&quot; → 其实是接口返回了空数组，不是前端渲染问题</span></span>
<span class="line"><span>- &quot;登录失败&quot; → 看响应是 401（凭证错）还是 400（参数错）</span></span>
<span class="line"><span>- &quot;页面慢&quot; → Timing 显示 TTFB 很高，是后端慢，不是前端</span></span></code></pre></div><blockquote><p>复现问题时勾选 <strong>Preserve log</strong>，页面跳转后网络记录不丢失。勾选 <strong>Disable cache</strong>，避免缓存干扰调试。</p></blockquote><h2 id="性能分析-找到慢在哪里" tabindex="-1">性能分析：找到慢在哪里 <a class="header-anchor" href="#性能分析-找到慢在哪里" aria-label="Permalink to &quot;性能分析：找到慢在哪里&quot;">​</a></h2><p>&quot;感觉卡&quot;不是定位问题的说法。用 Performance 面板录制一段交互，看时间花在哪：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 打开 Performance 面板</span></span>
<span class="line"><span>2. 点 Record → 操作页面（如滚动、点击）</span></span>
<span class="line"><span>3. Stop → 看 Flame Chart 和 Summary</span></span></code></pre></div><table tabindex="0"><thead><tr><th>火焰图颜色</th><th>含义</th></tr></thead><tbody><tr><td>黄色</td><td>脚本执行（JS）</td></tr><tr><td>紫色</td><td>布局和样式计算</td></tr><tr><td>绿色</td><td>绘制和合成</td></tr><tr><td>灰色</td><td>空闲</td></tr></tbody></table><table tabindex="0"><thead><tr><th>问题信号</th><th>可能原因</th></tr></thead><tbody><tr><td>长黄色块（&gt;50ms）</td><td>JS 计算太重，需要拆分</td></tr><tr><td>大块紫色</td><td>频繁重排（改了布局属性）</td></tr><tr><td>强制同步布局警告</td><td>读布局属性后又立刻写布局</td></tr></tbody></table><blockquote><p>别只看&quot;总时长&quot;。找到最长的那一段函数调用，针对性优化。优化后再录制对比，确认真的变快了。</p></blockquote><h2 id="移动端远程调试" tabindex="-1">移动端远程调试 <a class="header-anchor" href="#移动端远程调试" aria-label="Permalink to &quot;移动端远程调试&quot;">​</a></h2><p>手机上的问题没法直接用电脑 DevTools。用远程调试把手机连到电脑：</p><table tabindex="0"><thead><tr><th>平台</th><th>方法</th></tr></thead><tbody><tr><td>Android + Chrome</td><td><code>chrome://inspect</code>，USB 连接</td></tr><tr><td>iOS + Safari</td><td>Safari → 开发 → 设备名</td></tr><tr><td>微信/小程序</td><td>各自的开发者工具远程调试</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Android 调试步骤：</span></span>
<span class="line"><span>// 1. 手机开启开发者模式 + USB 调试</span></span>
<span class="line"><span>// 2. USB 连电脑</span></span>
<span class="line"><span>// 3. 电脑 Chrome 打开 chrome://inspect</span></span>
<span class="line"><span>// 4. 看到设备后点 Inspect</span></span></code></pre></div><p>移动端远程调试能看断点、网络、控制台，和桌面端几乎一样。无法远程调试时（如线上问题），用 <code>vConsole</code> 或 <code>eruda</code> 这类注入工具在页面内显示一个简易调试面板。</p><h2 id="日志策略-留有用的信息" tabindex="-1">日志策略：留有用的信息 <a class="header-anchor" href="#日志策略-留有用的信息" aria-label="Permalink to &quot;日志策略：留有用的信息&quot;">​</a></h2><p>线上问题靠日志复盘。但日志不是越多越好——关键在于<strong>留有用的信息</strong>：</p><table tabindex="0"><thead><tr><th>原则</th><th>说明</th></tr></thead><tbody><tr><td>记上下文</td><td><code>submit failed</code> 没用，<code>submit failed: form=login, error=network</code> 有用</td></tr><tr><td>分级别</td><td>error/warn/info，不要全是 log</td></tr><tr><td>避免敏感信息</td><td>密码、token 不要打日志</td></tr><tr><td>生产环境收敛</td><td>大量 console.log 影响性能，生产构建移除或降级</td></tr></tbody></table><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 差：看不出上下文</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;error&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, err)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 好：带上下文</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">error</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;[login] submit failed&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { email, code: err.code, msg: err.message })</span></span></code></pre></div><h2 id="常见-bug-排查清单" tabindex="-1">常见 bug 排查清单 <a class="header-anchor" href="#常见-bug-排查清单" aria-label="Permalink to &quot;常见 bug 排查清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>先查什么</th></tr></thead><tbody><tr><td>数据没显示</td><td>Network 响应体是否为空或报错</td></tr><tr><td>样式没生效</td><td>DevTools Elements 看 computed style，是否被覆盖</td></tr><tr><td>点击没反应</td><td>控制台是否有 JS 报错，元素是否被遮挡</td></tr><tr><td>偶发崩溃</td><td>是否有未处理的 Promise rejection</td></tr><tr><td>内存增长</td><td>Performance Memory 录制，看是否有泄漏</td></tr></tbody></table><h2 id="务实的检查清单" tabindex="-1">务实的检查清单 <a class="header-anchor" href="#务实的检查清单" aria-label="Permalink to &quot;务实的检查清单&quot;">​</a></h2><ul><li>是否先稳定复现 bug，再开始排查？</li><li>复杂问题是否用断点而非一堆 console.log？</li><li>条件断点是否用上，定位循环里的特定迭代？</li><li>接口问题是否先看 Network 面板的请求和响应？</li><li>&quot;页面卡&quot;是否用 Performance 录制找到具体慢的函数？</li><li>移动端问题是否用远程调试，而不是猜？</li><li>日志是否带上下文且不泄露敏感信息？</li></ul><p>调试的本质是&quot;缩小搜索范围&quot;。每一步操作（复现、隔离、断点、看网络）都应该让可能的原因变少。如果改了十次还没定位，说明方法错了——停下来，重新观察，而不是继续乱试。</p>`,41)])])}const u=a(d,[["render",i]]);export{b as __pageData,u as default};
